TAG = '<script src="/cgem-static/cgem_badges.js?v=1" defer></script>'
ESC_TAG = '&lt;script src=&quot;/cgem-static/cgem_badges.js?v=1&quot;&gt;&lt;/script&gt;'


def main():
    d = '/app/cgem/chat'
    os.makedirs(d, exist_ok=True)
    with open(os.path.join(d, 'cgem_badges.js'), 'w', encoding='utf-8') as f:
        f.write(BADGES_JS)
    # main pages: load the script together with the chat widget
    p = '/app/cgem/cgem_chat.py'
    try:
        s = open(p, encoding='utf-8').read()
        if 'cgem_badges.js' not in s:
            s = s.replace("SCRIPT_TAG = ('<script src=\"/cgem-static/cgem_i18n.js", "SCRIPT_TAG = ('" + TAG.replace("'", "\\'") + "'\n              '<script src=\"/cgem-static/cgem_i18n.js", 1)
            open(p, 'w', encoding='utf-8').write(s)
            print('v99s: SCRIPT_TAG patched', 'cgem_badges.js' in s)
    except Exception as e:
        print('v99s: chat patch failed', e)
    # chart iframes (sandboxed srcdoc pages) get the script too
    try:
        from superset.app import create_app
        app = create_app()
        with app.app_context():
            from superset.extensions import db
            from superset.models.slice import Slice
            n = 0
            for sl in db.session.query(Slice).all():
                try:
                    pr = json.loads(sl.params or '{}')
                except Exception:
                    continue
                t = pr.get('handlebarsTemplate')
                if not t or 'srcdoc=' not in t or 'cgem_badges.js' in t:
                    continue
                parts = t.split('&lt;/body&gt;')
                if len(parts) < 2:
                    continue
                pr['handlebarsTemplate'] = '&lt;/body&gt;'.join(parts[:-1]) + ESC_TAG + '&lt;/body&gt;' + parts[-1]
                sl.params = json.dumps(pr)
                n += 1
            db.session.commit()
            print('v99s: iframe charts patched', n)
    except Exception as e:
        print('v99s: iframe patch failed', e)


if __name__ == '__main__':
    main()
